"""Git worktree helpers for project-local quest creation."""

from __future__ import annotations

import os
import re
import shutil
import subprocess
from pathlib import Path

from .quest_types import QuestMeta

_PROJECT_NAME_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9_-]*$")


class SourceCheckoutError(Exception):
    """Source Sheaf checkout is not ready for quest creation."""


class SourceCheckoutDetached(SourceCheckoutError):
    def __init__(self, repo_path: str) -> None:
        self.repo_path = repo_path
        super().__init__(
            f"Source checkout is detached HEAD; checkout a named branch before "
            f"creating a quest: {repo_path}"
        )


class SourceCheckoutNotClean(SourceCheckoutError):
    def __init__(self, repo_path: str, status_output: str) -> None:
        self.repo_path = repo_path
        self.status_output = status_output
        super().__init__(
            f"Source checkout has uncommitted changes; commit or discard them "
            f"before creating a quest: {repo_path}\n{status_output}"
        )


class WorktreeCreationError(Exception):
    """Quest scaffold commit succeeded but worktree creation failed."""

    def __init__(
        self,
        message: str,
        *,
        quest_dir: Path,
        quest_create_commit: str,
    ) -> None:
        self.quest_dir = quest_dir
        self.quest_create_commit = quest_create_commit
        super().__init__(message)


def validate_project_name(project: str) -> None:
    if not _PROJECT_NAME_RE.match(project):
        raise ValueError(
            f"Invalid project name {project!r}; expected "
            r"^[A-Za-z0-9][A-Za-z0-9_-]*$"
        )


def quest_worktree_name(
    project: str,
    quest_type: str,
    quest_number: int,
    quest_slug: str,
) -> str:
    return f"{project}_{quest_type}_{quest_number:04d}_{quest_slug}"


def quest_worktree_branch(worktree_name: str) -> str:
    return f"quest/{worktree_name}"


def quest_worktree_base_dir(source_repo_root: Path) -> Path:
    return source_repo_root.resolve().parent / ".quest-worktrees"


def quest_worktree_path(source_repo_root: Path, meta: QuestMeta) -> Path:
    name = quest_worktree_name(
        meta.project,
        meta.quest_type,
        meta.quest_number,
        meta.quest_slug,
    )
    return quest_worktree_base_dir(source_repo_root) / name


def _git_env() -> dict[str, str]:
    env = os.environ.copy()
    env.setdefault("GIT_AUTHOR_NAME", "quest-runner")
    env.setdefault("GIT_AUTHOR_EMAIL", "quest-runner@local")
    env.setdefault("GIT_COMMITTER_NAME", "quest-runner")
    env.setdefault("GIT_COMMITTER_EMAIL", "quest-runner@local")
    return env


def run_git(
    git_dir: Path,
    *args: str,
    check: bool = True,
) -> subprocess.CompletedProcess[str]:
    return subprocess.run(
        ["git", "-C", str(git_dir), *args],
        check=check,
        capture_output=True,
        text=True,
        env=_git_env(),
    )


def _git(
    source_repo_root: Path,
    *args: str,
    check: bool = True,
) -> subprocess.CompletedProcess[str]:
    return run_git(source_repo_root, *args, check=check)


def current_branch(source_repo_root: Path) -> str:
    r = _git(source_repo_root, "branch", "--show-current", check=False)
    if r.returncode != 0:
        raise SourceCheckoutError(
            f"Failed to read current branch in {source_repo_root}: {r.stderr.strip()}"
        )
    branch = r.stdout.strip()
    if not branch:
        raise SourceCheckoutDetached(str(source_repo_root))
    return branch


def assert_source_checkout_clean(source_repo_root: Path) -> str:
    branch = current_branch(source_repo_root)
    status = _git(source_repo_root, "status", "--porcelain", check=False)
    if status.returncode != 0:
        raise SourceCheckoutError(
            f"Failed to read git status in {source_repo_root}: {status.stderr.strip()}"
        )
    dirty = status.stdout.strip()
    if dirty:
        raise SourceCheckoutNotClean(str(source_repo_root), dirty)
    return branch


def is_git_worktree(path: Path) -> bool:
    r = subprocess.run(
        ["git", "-C", str(path), "rev-parse", "--is-inside-work-tree"],
        check=False,
        capture_output=True,
        text=True,
    )
    return r.returncode == 0 and r.stdout.strip().lower() == "true"


def worktree_exists(source_repo_root: Path, meta: QuestMeta) -> bool:
    path = quest_worktree_path(source_repo_root, meta)
    if not path.is_dir():
        return False
    return is_git_worktree(path)


def create_quest_scaffold_commit(
    source_repo_root: Path,
    quest_dir: Path,
    *,
    project: str,
    quest_type: str,
    quest_number: int,
    quest_slug: str,
) -> str:
    rel = quest_dir.resolve().relative_to(source_repo_root.resolve()).as_posix()
    _git(source_repo_root, "add", "--", rel)
    message = f"quest-create: {project}/{quest_type}/{quest_number:04d}_{quest_slug}"
    _git(source_repo_root, "commit", "-m", message)
    rev = _git(source_repo_root, "rev-parse", "HEAD")
    return rev.stdout.strip()


def create_quest_worktree(source_repo_root: Path, meta: QuestMeta) -> Path:
    worktree_path = quest_worktree_path(source_repo_root, meta)
    branch = quest_worktree_branch(
        quest_worktree_name(
            meta.project,
            meta.quest_type,
            meta.quest_number,
            meta.quest_slug,
        )
    )
    worktree_path.parent.mkdir(parents=True, exist_ok=True)
    _git(
        source_repo_root,
        "worktree",
        "add",
        "-b",
        branch,
        str(worktree_path),
        "HEAD",
    )
    return worktree_path


def remove_partial_worktree(
    source_repo_root: Path,
    meta: QuestMeta,
    *,
    remove_branch: bool = True,
) -> None:
    worktree_path = quest_worktree_path(source_repo_root, meta)
    branch = quest_worktree_branch(
        quest_worktree_name(
            meta.project,
            meta.quest_type,
            meta.quest_number,
            meta.quest_slug,
        )
    )
    if worktree_path.is_dir():
        _git(
            source_repo_root,
            "worktree",
            "remove",
            "--force",
            str(worktree_path),
            check=False,
        )
        if worktree_path.exists():
            shutil.rmtree(worktree_path, ignore_errors=True)
    if remove_branch:
        _git(source_repo_root, "branch", "-D", branch, check=False)


def is_worktree_clean(worktree_path: Path) -> bool:
    clean, _dirty = porcelain_status(worktree_path)
    return clean


def porcelain_status(git_dir: Path) -> tuple[bool, str]:
    status = run_git(git_dir, "status", "--porcelain", check=False)
    if status.returncode != 0:
        raise SourceCheckoutError(
            f"Failed to read git status in {git_dir}: {status.stderr.strip()}"
        )
    output = status.stdout.strip()
    return (not output, output)


def branch_exists(git_dir: Path, branch: str) -> bool:
    result = run_git(
        git_dir,
        "show-ref",
        "--verify",
        f"refs/heads/{branch}",
        check=False,
    )
    return result.returncode == 0


def checkout_branch(git_dir: Path, branch: str) -> None:
    run_git(git_dir, "checkout", branch)


def rebase_onto(worktree_path: Path, onto_branch: str) -> subprocess.CompletedProcess[str]:
    return run_git(worktree_path, "rebase", onto_branch, check=False)


def merge_ff_only(git_dir: Path, branch: str) -> subprocess.CompletedProcess[str]:
    return run_git(git_dir, "merge", "--ff-only", branch, check=False)


def remove_worktree(source_repo_root: Path, worktree_path: Path) -> subprocess.CompletedProcess[str]:
    return run_git(
        source_repo_root,
        "worktree",
        "remove",
        str(worktree_path),
        check=False,
    )


def delete_branch(git_dir: Path, branch: str) -> subprocess.CompletedProcess[str]:
    return run_git(git_dir, "branch", "-d", branch, check=False)


def rev_parse_head(git_dir: Path) -> str:
    result = run_git(git_dir, "rev-parse", "HEAD")
    return result.stdout.strip()

"""Quest Runner command-line interface wrapping the REST service."""

from __future__ import annotations

import argparse
import json
import os
import sys
import textwrap
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Callable, TextIO
from urllib.error import HTTPError, URLError
from urllib.parse import urlencode, urljoin
from urllib.request import Request, urlopen

_DEFAULT_BASE_URL = "http://localhost:9002"
_SERVICE_NAME = "quest-runner"
_VALID_QUEST_TYPES = frozenset({"main", "side"})
_VALID_SCOPES = frozenset({"physicalplan", "polishing"})
_VALID_STATUSES = frozenset({"open", "completed", "all"})
_VALID_ISSUE_STATUSES = frozenset({"open", "completed"})
_VALID_OUTCOMES = frozenset({"Fixed", "NotFixed"})


class CliValidationError(Exception):
    pass


class TransportError(Exception):
    def __init__(
        self,
        message: str,
        *,
        base_url: str | None = None,
        endpoint: str | None = None,
    ) -> None:
        super().__init__(message)
        self.base_url = base_url
        self.endpoint = endpoint


@dataclass(frozen=True)
class RecordedRequest:
    method: str
    url: str
    body: dict[str, Any] | None


RequestFn = Callable[[str, str, dict[str, Any] | None], tuple[int, dict[str, Any]]]


def _script_start_path(argv: list[str] | None) -> Path:
    if argv is None:
        return Path(sys.argv[0]).resolve()
    if not argv:
        return Path.cwd()
    return Path(argv[0]).resolve()


def _find_repo_root(start: Path) -> Path | None:
    current = start.resolve()
    if current.is_file():
        current = current.parent
    for directory in (current, *current.parents):
        if (directory / "config" / "services.json").is_file():
            return directory
    return None


def _normalize_host(host: str) -> str:
    if host.strip() == "0.0.0.0":
        return "localhost"
    return host.strip()


def _service_url_from_config(repo_root: Path) -> str | None:
    config_path = repo_root / "config" / "services.json"
    try:
        raw = json.loads(config_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return None
    if not isinstance(raw, list):
        return None
    for entry in raw:
        if not isinstance(entry, dict):
            continue
        if entry.get("name") != _SERVICE_NAME:
            continue
        host = entry.get("host")
        port = entry.get("port")
        if not host or port is None:
            return None
        return f"http://{_normalize_host(str(host))}:{port}"
    return None


def resolve_base_url(
    *,
    cli_base_url: str | None = None,
    env: dict[str, str] | None = None,
    start_path: Path | None = None,
) -> tuple[str, str | None]:
    """Return (base_url, warning_message). warning is None when no fallback was used."""
    if cli_base_url:
        return cli_base_url.rstrip("/"), None

    environment = os.environ if env is None else env
    env_url = environment.get("QUEST_RUNNER_URL", "").strip()
    if env_url:
        return env_url.rstrip("/"), None

    anchor = start_path if start_path is not None else Path.cwd()
    repo_root = _find_repo_root(anchor)
    if repo_root is not None:
        from_config = _service_url_from_config(repo_root)
        if from_config:
            return from_config.rstrip("/"), None

    return _DEFAULT_BASE_URL, (
        f"Could not resolve quest-runner service URL from config/services.json; "
        f"using fallback {_DEFAULT_BASE_URL}"
    )


def default_request(method: str, url: str, body: dict[str, Any] | None) -> tuple[int, dict[str, Any]]:
    headers = {
        "Accept": "application/json",
        "Content-Type": "application/json",
    }
    payload = None
    if body is not None:
        payload = json.dumps(body).encode("utf-8")
    request = Request(url, data=payload, method=method, headers=headers)
    try:
        with urlopen(request) as response:
            text = response.read().decode("utf-8")
            status = response.status
    except HTTPError as exc:
        text = exc.read().decode("utf-8")
        status = exc.code
    except URLError as exc:
        raise TransportError(str(exc.reason)) from exc

    if not text.strip():
        return status, {}
    try:
        parsed = json.loads(text)
    except json.JSONDecodeError:
        parsed = {"error": text}
    if not isinstance(parsed, dict):
        return status, {"data": parsed}
    return status, parsed


def _endpoint_path(path: str) -> str:
    return path if path.startswith("/") else f"/{path}"


def _join_url(base_url: str, path: str, query: dict[str, Any] | None = None) -> str:
    url = urljoin(f"{base_url.rstrip('/')}/", _endpoint_path(path).lstrip("/"))
    if query:
        filtered = {key: value for key, value in query.items() if value is not None}
        if filtered:
            url = f"{url}?{urlencode(filtered, doseq=True)}"
    return url


def _send_request(
    request_fn: RequestFn,
    method: str,
    *,
    base_url: str,
    endpoint: str,
    body: dict[str, Any] | None,
    query: dict[str, Any] | None = None,
) -> tuple[int, dict[str, Any]]:
    try:
        return request_fn(method, _join_url(base_url, endpoint, query), body)
    except TransportError as exc:
        if exc.base_url is not None and exc.endpoint is not None:
            raise
        raise TransportError(str(exc), base_url=base_url, endpoint=endpoint) from exc


def _quest_dashboard_url(base_url: str, project: str, quest_type: str, quest_number: int) -> str:
    query = urlencode(
        {
            "project": project,
            "quest_type": quest_type,
            "quest_number": str(quest_number),
        }
    )
    return f"{base_url.rstrip('/')}/dashboard?{query}"


def _read_text_source(body: str | None, body_file: str | None, label: str) -> str:
    if body is not None and body_file is not None:
        raise CliValidationError(f"--{label} and --{label}-file are mutually exclusive")
    if body_file is not None:
        try:
            return Path(body_file).read_text(encoding="utf-8")
        except OSError as exc:
            raise CliValidationError(f"Could not read --{label}-file: {exc}") from exc
    if body is None:
        raise CliValidationError(f"--{label} or --{label}-file is required")
    return body


def _validate_quest_type(quest_type: str) -> None:
    if quest_type not in _VALID_QUEST_TYPES:
        raise CliValidationError("--type must be 'main' or 'side'")


def _validate_scope(scope: str) -> None:
    if scope not in _VALID_SCOPES:
        raise CliValidationError("--scope must be 'physicalplan' or 'polishing'")


def _validate_list_status(status: str) -> None:
    if status not in _VALID_STATUSES:
        raise CliValidationError("--status must be 'open', 'completed', or 'all'")


def _validate_issue_status(status: str) -> None:
    if status not in _VALID_ISSUE_STATUSES:
        raise CliValidationError("--status must be 'open' or 'completed'")


def _validate_outcome(outcome: str) -> None:
    if outcome not in _VALID_OUTCOMES:
        raise CliValidationError("--outcome must be 'Fixed' or 'NotFixed'")


def _validate_slice_for_scope(scope: str, slice_number: int | None) -> None:
    if scope == "physicalplan" and slice_number is not None:
        raise CliValidationError("--slice must not be used with --scope physicalplan")
    if scope == "polishing" and slice_number is None:
        raise CliValidationError("--slice is required for --scope polishing")


def _issue_query(
    project: str,
    quest_type: str,
    quest_number: int,
    scope: str,
    slice_number: int | None,
    extra: dict[str, Any] | None = None,
) -> dict[str, Any]:
    query: dict[str, Any] = {
        "project": project,
        "quest_type": quest_type,
        "quest_number": quest_number,
        "scope": scope,
    }
    if slice_number is not None:
        query["slice"] = slice_number
    if extra:
        query.update(extra)
    return query


def _issue_body(
    project: str,
    quest_type: str,
    quest_number: int,
    scope: str,
    slice_number: int | None,
    extra: dict[str, Any] | None = None,
) -> dict[str, Any]:
    body: dict[str, Any] = {
        "project": project,
        "quest_type": quest_type,
        "quest_number": quest_number,
        "scope": scope,
        "slice": slice_number,
    }
    if extra:
        body.update(extra)
    return body


def _print_json(data: dict[str, Any], out: TextIO) -> None:
    out.write(json.dumps(data, indent=2, sort_keys=True))
    out.write("\n")


def _print_field(label: str, value: Any, out: TextIO) -> None:
    if value is None:
        return
    out.write(f"{label}: {value}\n")


def _print_table(headers: list[str], rows: list[list[str]], out: TextIO) -> None:
    if not rows:
        out.write("(none)\n")
        return
    widths = [len(header) for header in headers]
    for row in rows:
        for index, cell in enumerate(row):
            widths[index] = max(widths[index], len(cell))
    header_line = "  ".join(
        header.ljust(widths[index]) for index, header in enumerate(headers)
    )
    out.write(header_line + "\n")
    out.write("  ".join("-" * width for width in widths) + "\n")
    for row in rows:
        out.write(
            "  ".join(cell.ljust(widths[index]) for index, cell in enumerate(row))
            + "\n"
        )


def _format_create(data: dict[str, Any], base_url: str, out: TextIO) -> None:
    _print_field("project", data.get("project"), out)
    _print_field("quest_type", data.get("quest_type"), out)
    _print_field("quest_number", data.get("quest_number"), out)
    _print_field("quest_slug", data.get("quest_slug"), out)
    _print_field("quest_dir", data.get("quest_dir"), out)
    _print_field("worktree_branch", data.get("worktree_branch"), out)
    _print_field("worktree_path", data.get("worktree_path"), out)
    dashboard_url = data.get("dashboard_url")
    if dashboard_url is None and all(
        key in data for key in ("project", "quest_type", "quest_number")
    ):
        dashboard_url = _quest_dashboard_url(
            base_url,
            str(data["project"]),
            str(data["quest_type"]),
            int(data["quest_number"]),
        )
    _print_field("dashboard_url", dashboard_url, out)


def _format_run(data: dict[str, Any], out: TextIO) -> None:
    _print_field("run_id", data.get("run_id"), out)
    _print_field("status", data.get("status"), out)
    _print_field("quest_url", data.get("quest_url"), out)
    _print_field("status_url", data.get("status_url"), out)


def _format_advance(data: dict[str, Any], out: TextIO) -> None:
    _print_field("status", data.get("status"), out)
    if data.get("status") == "completed":
        _print_field("advanced", data.get("advanced"), out)
        return
    _print_field("previous_state", data.get("previous_state"), out)
    _print_field("next_state", data.get("next_state"), out)
    _print_field("active_slice", data.get("active_slice"), out)
    _print_field("previous_slice_state", data.get("previous_slice_state"), out)
    _print_field("next_slice_state", data.get("next_slice_state"), out)
    _print_field("commit", data.get("commit"), out)
    _print_field("message", data.get("message"), out)


def _format_land(data: dict[str, Any], out: TextIO) -> None:
    _print_field("status", data.get("status"), out)
    _print_field("target_branch", data.get("target_branch"), out)
    _print_field("worktree_branch", data.get("worktree_branch"), out)
    _print_field("rebased", data.get("rebased"), out)

"""Flask REST API for the Quest Runner service."""

from __future__ import annotations

import json
import logging
from collections.abc import Callable
from pathlib import Path

from flask import Flask, jsonify, request, send_from_directory
from flask_sock import Sock

from . import dashboard_data
from . import dashboard_git
from . import dashboard_slice
from .dashboard_chat import ChatStreamSession
from .dashboard_data import DashboardBadRequest, DashboardNotFound
from .harness import HarnessNotAvailable
from .quest_fs import QuestStateParseError
from .issue_service import IssueNotFound
from .quest_service import (
    AdvanceQuestConflict,
    AdvanceQuestValidationError,
    FatalInvariantError,
    InvalidProject,
    InvalidQuestInput,
    LandQuestConflict,
    MissingDefaultExecutionConfig,
    MissingQuestWorktree,
    NotAGitRepo,
    QuestLockContention,
    QuestNotFound,
    QuestService,
    RepoNotFound,
    SliceInitializationConflict,
)
from .worktrees import WorktreeCreationError

log = logging.getLogger("quest_runner")
_DASHBOARD_ASSETS_DIR = Path(__file__).resolve().parent / "dashboard_assets"


def _no_cache(resp):
    resp.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
    resp.headers["Pragma"] = "no-cache"
    resp.headers["Expires"] = "0"
    return resp


def create_app(
    quest_service: QuestService,
    source_repo_root: Path,
    started_at: float,
    shutdown_callback: Callable[[], None] | None = None,
) -> Flask:
    app = Flask(__name__)
    source_root = source_repo_root.resolve()
    sock = Sock(app)
    web_src_dir = source_root / "projects" / "web" / "src"

    @app.errorhandler(RepoNotFound)
    def handle_repo_not_found(exc):
        return jsonify({"error": str(exc)}), 404

    @app.errorhandler(NotAGitRepo)
    def handle_not_git_repo(exc):
        return jsonify({"error": str(exc)}), 422

    @app.errorhandler(InvalidProject)
    def handle_invalid_project(exc):
        return jsonify({"error": str(exc)}), 400

    @app.errorhandler(InvalidQuestInput)
    def handle_invalid_quest_input(exc):
        return jsonify({"error": str(exc)}), 400

    @app.errorhandler(QuestLockContention)
    def handle_lock_contention(exc):
        return jsonify({
            "error": str(exc),
            "repo_path": exc.repo_path,
            "lock_owner": {
                "quest_type": exc.lock_info.quest_type,
                "quest_number": exc.lock_info.quest_number,
                "request_id": exc.lock_info.request_id,
            },
        }), 409

    @app.errorhandler(QuestNotFound)
    def handle_quest_not_found(exc):
        return jsonify({"error": str(exc)}), 404

    @app.errorhandler(MissingQuestWorktree)
    def handle_missing_quest_worktree(exc):
        return jsonify({
            "error": str(exc),
            "project": exc.project,
            "quest_type": exc.quest_type,
            "quest_number": exc.quest_number,
            "expected_worktree": str(exc.worktree_path),
        }), 409

    @app.errorhandler(FatalInvariantError)
    def handle_fatal_invariant(exc):
        return jsonify({"error": str(exc)}), 500

    @app.errorhandler(MissingDefaultExecutionConfig)
    def handle_missing_default_execution_config(exc):
        return jsonify({"error": str(exc)}), 500

    @app.errorhandler(WorktreeCreationError)
    def handle_worktree_creation_error(exc):
        return jsonify({"error": str(exc)}), 500

    @app.errorhandler(HarnessNotAvailable)
    def handle_harness_not_available(exc):
        return jsonify({"error": str(exc)}), 503

    @app.errorhandler(QuestStateParseError)
    def handle_quest_state_parse_error(exc):
        return jsonify({"error": str(exc)}), 422

    @app.errorhandler(AdvanceQuestValidationError)
    def handle_advance_quest_validation(exc):
        return jsonify({"error": exc.message, "reason": exc.reason}), 422

    @app.errorhandler(AdvanceQuestConflict)
    def handle_advance_quest_conflict(exc):
        return jsonify({"error": exc.message}), 409

    @app.errorhandler(LandQuestConflict)
    def handle_land_quest_conflict(exc):
